package net.officefloor.hq.app.invoices;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import org.hibernate.annotations.Formula;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** An invoice raised for a client, made of lines. */
@Entity
@Table(name = "invoice")
public class Invoice {

    /** A due date set by hand can be at most this many days after the issue date. */
    public static final int MAX_DUE_DAYS = 120;

    /** Payments that leave less than this still due have the rest written off. */
    public static final BigDecimal WRITE_OFF_LIMIT = new BigDecimal("1.00");

    /** A part payment must be at least this share of the grand total, unless it settles the invoice. */
    public static final BigDecimal MINIMUM_PART_SHARE = new BigDecimal("0.10");

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id")
    private Long clientId;

    @Enumerated(EnumType.STRING)
    private InvoiceStatus status;

    @Column(name = "issue_date")
    private LocalDate issueDate;

    @Column(name = "due_date")
    private LocalDate dueDate;

    @Column(name = "manual_due_date")
    private boolean manualDueDate;

    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    @Column(name = "discount_amount")
    private BigDecimal discountAmount = BigDecimal.ZERO;

    @Column(name = "discount_cap")
    private BigDecimal discountCap;

    @Column(name = "discount_reason")
    private String discountReason;

    /** Whether the invoice's client is tax exempt, so no line is taxed; read from the client. */
    @Formula("(SELECT c.tax_exempt FROM client c WHERE c.id = client_id)")
    private boolean clientTaxExempt;

    /** The id of the invoice this credit note credits; null for an ordinary invoice. */
    @Column(name = "credit_of")
    private Long creditOf;

    /** An issued credit note's grand total, kept when it is issued; null until then. */
    @Column(name = "credit_total")
    private BigDecimal creditTotal;

    /** What the credit notes issued against this invoice add up to; read from them. */
    @Formula("(SELECT COALESCE(SUM(cn.credit_total), 0) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
    private BigDecimal credited = BigDecimal.ZERO;

    /** How many credit notes have been issued against this invoice; read from them. */
    @Formula("(SELECT COUNT(*) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
    private int creditNotesIssued;

    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true)
    @JoinColumn(name = "invoice_id", nullable = false)
    @OrderBy("id")
    private List<InvoiceLine> lines = new ArrayList<>();

    protected Invoice() {
    }

    /** A new, empty draft for a client, issued and due on the given dates. */
    public static Invoice draft(Long clientId, boolean clientTaxExempt, LocalDate issueDate, LocalDate dueDate) {
        Invoice invoice = new Invoice();
        invoice.clientId = clientId;
        invoice.clientTaxExempt = clientTaxExempt;
        invoice.status = InvoiceStatus.DRAFT;
        invoice.issueDate = issueDate;
        invoice.dueDate = dueDate;
        return invoice;
    }

    /**
     * A new draft for the same client with copies of this invoice's lines and the same invoice
     * discount, issued and due on the given dates. Payments stay with this invoice.
     */
    public Invoice duplicate(LocalDate issueDate, LocalDate dueDate) {
        Invoice copy = draft(clientId, clientTaxExempt, issueDate, dueDate);
        copy.discountPct = discountPct;
        copy.discountAmount = discountAmount;
        copy.discountCap = discountCap;
        copy.discountReason = discountReason;
        lines.forEach(line -> copy.lines.add(line.copy()));
        return copy;
    }

    /**
     * A new, empty draft credit note for the sent invoice, issued on the given date: same client, no
     * discount, taxed as the original's lines are.
     */
    public Invoice creditNote(LocalDate issueDate) {
        Invoice note = draft(clientId, clientTaxExempt, issueDate, null);
        note.creditOf = id;
        return note;
    }

    /** Whether this is a credit note against another invoice. */
    public boolean isCreditNote() {
        return creditOf != null;
    }

    /** The id of the invoice this credit note credits; null for an ordinary invoice. */
    public Long getCreditOf() {
        return creditOf;
    }

    /** The number shown: CN-... for a credit note, otherwise INV-... (see {@link InvoiceNumber}). */
    public String number() {
        return isCreditNote() ? InvoiceNumber.creditNoteOf(id) : InvoiceNumber.of(id);
    }

    /** What the credit notes issued against this invoice add up to, to the cent. */
    public BigDecimal getCredited() {
        return (credited == null ? BigDecimal.ZERO : credited).setScale(2, RoundingMode.HALF_UP);
    }

    /** Whether a credit note has been issued against this invoice: it can then no longer change. */
    public boolean hasCreditNotesIssued() {
        return creditNotesIssued > 0;
    }

    /** Issues a draft credit note on the given date, keeping its grand total at the tax rate. */
    public void markIssued(LocalDate issueDate, BigDecimal taxRate) {
        this.creditTotal = total(taxRate);
        this.status = InvoiceStatus.CREDIT_NOTE;
        this.issueDate = issueDate;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssueDate() {
        return issueDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** The percentage taken off the subtotal, 0 to 100 with up to two decimals. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** The fixed amount taken off the subtotal, to the cent; 0 when the discount is a percentage. */
    public BigDecimal getDiscountAmount() {
        return discountAmount;
    }

    /** The most taken off the invoice in all, line discounts included, to the cent; null when there is no cap. */
    public BigDecimal getDiscountCap() {
        return discountCap;
    }

    /** Why the discount was given; null when no reason was given. */
    public String getDiscountReason() {
        return discountReason;
    }

    /** Sets why the discount was given; blank is no reason. */
    public void setDiscountReason(String discountReason) {
        this.discountReason = discountReason == null || discountReason.isBlank() ? null : discountReason.strip();
    }

    /** Whether the discount takes off more than a fifth of the subtotal, after any cap, and so needs a reason. */
    public boolean discountNeedsReason() {
        return discount().multiply(BigDecimal.valueOf(5)).compareTo(subtotal()) > 0;
    }

    /** Whether the discount needs a reason but has none. */
    public boolean discountLacksReason() {
        return discountNeedsReason() && discountReason == null;
    }

    /** Sets the percentage taken off the subtotal, clearing any fixed amount; it has already been checked. */
    public void setDiscountPct(BigDecimal discountPct) {
        this.discountPct = discountPct;
        this.discountAmount = BigDecimal.ZERO;
    }

    /** Sets the most taken off the invoice in all, or null for no cap; it has already been checked as money. */
    public void setDiscountCap(BigDecimal discountCap) {
        this.discountCap = discountCap;
    }

    /**
     * Sets a fixed amount taken off the subtotal, clearing any percentage; it has already been checked
     * as money. An amount over the subtotal is refused.
     */
    public void setDiscountAmount(BigDecimal discountAmount) {
        if (discountAmount.compareTo(subtotal()) > 0) {
            throw new InvoiceRejectedException("The discount cannot be more than the subtotal of "
                    + subtotal().toPlainString() + ".");
        }
        this.discountAmount = discountAmount;
        this.discountPct = BigDecimal.ZERO;
    }

    public List<InvoiceLine> getLines() {
        return lines;
    }

    /** Whether lines can still be added: only a draft is still being written. */
    public boolean isDraft() {
        return status == InvoiceStatus.DRAFT;
    }

    /** Whether the invoice has been voided: it no longer counts, takes no payments and cannot be changed. */
    public boolean isVoid() {
        return status == InvoiceStatus.VOID;
    }

    /** Voids a sent invoice. */
    public void markVoid() {
        this.status = InvoiceStatus.VOID;
    }

    /** Whether the due date was set by hand; it is then kept when the invoice is sent. */
    public boolean isManualDueDate() {
        return manualDueDate;
    }

    /**
     * Sets the due date by hand: not before the issue date nor more than {@link #MAX_DUE_DAYS} days
     * after it, or it is refused.
     */
    public void setDueDate(LocalDate dueDate) {
        if (issueDate != null && dueDate.isBefore(issueDate)) {
            throw new InvoiceRejectedException(
                    "The due date cannot be before the issue date (" + issueDate + ").");
        }
        if (issueDate != null && dueDate.isAfter(issueDate.plusDays(MAX_DUE_DAYS))) {
            throw new InvoiceRejectedException("The due date can be at most " + MAX_DUE_DAYS
                    + " days after the issue date, so no later than " + issueDate.plusDays(MAX_DUE_DAYS) + ".");
        }
        this.dueDate = dueDate;
        this.manualDueDate = true;
    }

    /**
     * Marks the invoice sent, issued on the given date and due on the given date, unless its due date
     * was set by hand, which is kept.
     */
    public void markSent(LocalDate issueDate, LocalDate dueDate) {
        this.status = InvoiceStatus.SENT;
        this.issueDate = issueDate;
        if (!manualDueDate) {
            this.dueDate = dueDate;
        }
    }

    /** Whether a due date set by hand is already past on the given send date. */
    public boolean dueDatePassedBy(LocalDate sendDate) {
        return manualDueDate && dueDate != null && dueDate.isBefore(sendDate);
    }

    /** Puts a sent invoice back to draft, so it has to be sent again. */
    public void reopen() {
        this.status = InvoiceStatus.DRAFT;
    }

    /** Days past its due date an invoice is given before it becomes overdue: a week's grace. */
    public static final int GRACE_DAYS = 7;

    /**
     * The status on the given day once the given amount has been paid against the grand total at the
     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
     * due date is overdue, part paid or not.
     */
    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
        return statusWhenPaid(paid, null, taxRate, today);
    }

    /**
     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
     * paid date (null when not known) is after its due date is paid late.
     */
    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
        if (status != InvoiceStatus.SENT) {
            return status;
        }
        boolean due = amountDue(paid, taxRate).signum() > 0;
        if (due && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
            return InvoiceStatus.OVERDUE;
        }
        if (paid.signum() <= 0) {
            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
        }
        if (due) {
            return InvoiceStatus.PART_PAID;
        }
        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
                : InvoiceStatus.PAID;
    }

    /**
     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
     * counts on the day it was applied); null while something is still due.
     */
    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
        BigDecimal total = total(taxRate).subtract(getCredited());
        if (status != InvoiceStatus.SENT || total.signum() <= 0) {
            return null;
        }
        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
        }
        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
        BigDecimal sum = BigDecimal.ZERO;
        for (Part p : inOrder) {
            sum = sum.add(p.amount());
            if (sum.signum() > 0 && total.subtract(sum).compareTo(WRITE_OFF_LIMIT) < 0) {
                return p.on();
            }
        }
        return null;
    }

    /**
     * What is still due once the given amount has been paid: the grand total less it, less what credit
     * notes have credited, less anything written off — so nothing once payments leave less than
     * {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
     */
    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
        if (isCreditNote()) {
            return BigDecimal.ZERO.setScale(2);
        }
        return total(taxRate).subtract(getCredited()).subtract(paid).subtract(writtenOff(paid, taxRate));
    }

    /**
     * What is written off once the given amount has been paid: when payments leave less than
     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
     */
    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
        BigDecimal left = total(taxRate).subtract(getCredited()).subtract(paid);
        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && left.compareTo(WRITE_OFF_LIMIT) < 0
                ? left.setScale(2, RoundingMode.HALF_UP)
                : BigDecimal.ZERO.setScale(2);
    }

    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
    public BigDecimal minimumPart(BigDecimal taxRate) {
        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * Whether paying the amount on top of what was already paid is too small a part payment: under
     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
     */
    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
    }

    /** Adds a line to the end of the invoice. */
    public void addLine(InvoiceLine line) {
        lines.add(line);
    }

    /** Whether the invoice has the line with the given id. */
    public boolean hasLine(Long lineId) {
        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
    }

    /**
     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
     * be less than a fixed discount on the invoice.
     */
    public boolean removeLine(Long lineId) {
        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
        if (line == null) {
            return false;
        }
        BigDecimal left = subtotal().subtract(line.amount());
        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
            throw new InvoiceRejectedException("This line cannot be removed: the $"
                    + left.setScale(2).toPlainString() + " left would be less than the $"
                    + discountAmount.setScale(2).toPlainString() + " discount.");
        }
        lines.remove(line);
        return true;
    }

    /**
     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
     * the subtotal would then be less than a fixed discount on the invoice.
     */
    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
        if (line == null) {
            return false;
        }
        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount();
        BigDecimal left = subtotal().subtract(line.amount()).add(changed);
        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
            throw new InvoiceRejectedException("This line cannot be changed: the $"
                    + left.setScale(2).toPlainString() + " subtotal would be less than the $"
                    + discountAmount.setScale(2).toPlainString() + " discount.");
        }
        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
        return true;
    }

    /**
     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
     * matches what a client gets by adding up the lines shown.
     */
    public BigDecimal subtotal() {
        return lines.stream().map(InvoiceLine::amount)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
     */
    public BigDecimal discount() {
        BigDecimal discount = discountAmount.signum() > 0
                ? discountAmount.min(subtotal()).setScale(2, RoundingMode.HALF_UP)
                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(2, RoundingMode.DOWN);
        if (discountCap == null) {
            return discount;
        }
        BigDecimal lineDiscounts = lines.stream().map(InvoiceLine::discount)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        BigDecimal left = discountCap.setScale(2, RoundingMode.HALF_UP).subtract(lineDiscounts).max(BigDecimal.ZERO.setScale(2));
        return discount.min(left);
    }

    /**
     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
     * proportion to the line amounts: each line first gets the whole cents of its exact share
     * (rounded down), then the cents left over go one each to the lines with the largest leftover
     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
     * equal amounts too to the lower line id. The shares add up to the discount.
     */
    public List<BigDecimal> discountShares() {
        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
        int n = lines.size();
        BigInteger[] shares = new BigInteger[n];
        BigInteger[] leftovers = new BigInteger[n];
        BigInteger given = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            if (subtotalCents.signum() == 0) {
                shares[i] = BigInteger.ZERO;
                leftovers[i] = BigInteger.ZERO;
            } else {
                // The exact share is discount * amount / subtotal; all fractions share the subtotal
                // as denominator, so the remainders compare as the fractions do.
                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
                        .divideAndRemainder(subtotalCents);
                shares[i] = qr[0];
                leftovers[i] = qr[1];
            }
            given = given.add(shares[i]);
        }
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            order.add(i);
        }
        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount()).reversed())
                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
        int left = discountCents.subtract(given).intValueExact();
        for (int k = 0; k < left; k++) {
            int i = order.get(k);
            shares[i] = shares[i].add(BigInteger.ONE);
        }
        List<BigDecimal> result = new ArrayList<>(n);
        for (BigInteger share : shares) {
            result.add(new BigDecimal(share, 2));
        }
        return result;
    }

    /**
     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
     */
    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
        List<BigDecimal> shares = discountShares();
        List<BigDecimal> taxes = new ArrayList<>(lines.size());
        for (int i = 0; i < lines.size(); i++) {
            InvoiceLine line = lines.get(i);
            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO.setScale(2)
                    : line.amount().subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
                            .setScale(2, RoundingMode.HALF_UP));
        }
        return taxes;
    }

    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
    public BigDecimal tax(BigDecimal taxRate) {
        return lineTaxes(taxRate).stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
    public BigDecimal total(BigDecimal taxRate) {
        return subtotal().subtract(discount()).add(tax(taxRate));
    }
}
package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than a week (the grace period) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 * A credit note is a draft until it is issued, when it becomes CREDIT_NOTE for good. A sent invoice
 * whose issued credit notes leave nothing due, with nothing paid, is credited; that follows from its
 * credit notes and is never stored.
 */
public enum InvoiceStatus {
    DRAFT, SENT, PART_PAID, PAID, PAID_LATE, OVERDUE, VOID, CREDIT_NOTE, CREDITED
}
package net.officefloor.hq.app.invoices;

import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.server.ResponseStatusException;

/** Turns a refused invoice change into a problem response whose detail says what is wrong. */
@RestControllerAdvice(assignableTypes = InvoiceController.class)
public class InvoiceErrors {

    private static final List<String> FIELD_ORDER = List.of("description", "qty", "unitPrice", "discountPct", "discountAmount", "discountCap", "discountReason", "discountGiven", "amount", "date", "reference", "dueDate");

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail invalid(MethodArgumentNotValidException e) {
        String detail = e.getBindingResult().getFieldErrors().stream()
                .sorted((a, b) -> Integer.compare(FIELD_ORDER.indexOf(a.getField()),
                        FIELD_ORDER.indexOf(b.getField())))
                .map(f -> f.getDefaultMessage())
                .distinct()
                .reduce((a, b) -> a + " " + b)
                .orElse("The change is not valid.");
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, detail);
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ProblemDetail unreadable(HttpMessageNotReadableException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,
                "Enter the numbers as numbers, like 1.5 and 12.35.");
    }

    @ExceptionHandler(ResponseStatusException.class)
    public ProblemDetail status(ResponseStatusException e) {
        return ProblemDetail.forStatusAndDetail(e.getStatusCode(), e.getReason());
    }

    @ExceptionHandler(InvoiceRejectedException.class)
    public ProblemDetail rejected(InvoiceRejectedException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }
}

package net.officefloor.hq.app.invoices;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.TaxRate;
import net.officefloor.hq.app.Today;
import net.officefloor.hq.app.clients.Client;
import net.officefloor.hq.app.clients.ClientRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Lists a client's invoices, opens one, starts new drafts, duplicates one, adds lines to them, gives them a discount,
 * sends them, voids them and records payments against them.
 */
@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final Today today;
    private final TaxRate taxRate;
    private final Audit audit;
    private final EntityManager entityManager;

    public InvoiceService(InvoiceRepository invoices, PaymentRepository payments, ClientRepository clients,
            Today today, TaxRate taxRate, Audit audit, EntityManager entityManager) {
        this.entityManager = entityManager;
        this.invoices = invoices;
        this.payments = payments;
        this.clients = clients;
        this.today = today;
        this.taxRate = taxRate;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Invoice> forClient(Long clientId) {
        return invoices.findByClientIdOrderByIdAsc(clientId);
    }

    /** Every invoice of every client, with its lines. */
    @Transactional(readOnly = true)
    public List<Invoice> all() {
        return invoices.findAllByOrderByIdAsc();
    }

    @Transactional(readOnly = true)
    public Optional<Invoice> find(Long id) {
        return invoices.findWithLinesById(id);
    }

    /**
     * An empty draft for the client, issued today, due on the client's terms and starting with the
     * client's standard discount; empty if no such client.
     */
    @Transactional
    public Optional<Invoice> newDraft(Long clientId) {
        return clients.findById(clientId).map(client -> {
            LocalDate issued = today.date();
            Invoice draft = Invoice.draft(clientId, client.isTaxExempt(), issued, dueDateFor(clientId, issued));
            draft.setDiscountPct(client.getDiscountPct());
            return invoices.save(draft);
        });
    }

    /**
     * A new draft for the invoice's client with copies of its lines and the same invoice discount,
     * issued today and due as any new invoice is, and records it in the audit; empty if no such
     * invoice. Payments are not copied.
     */
    @Transactional
    public Optional<Invoice> duplicate(Long invoiceId) {
        return invoices.findWithLinesById(invoiceId).map(original -> {
            if (original.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note cannot be duplicated.");
            }
            LocalDate issued = today.date();
            Invoice copy = invoices.saveAndFlush(original.duplicate(issued, dueDateFor(original.getClientId(), issued)));
            audit.record("INVOICE_DUPLICATED from=" + InvoiceNumber.of(original.getId())
                    + " to=" + InvoiceNumber.of(copy.getId()));
            return copy;
        });
    }

    /**
     * A new, empty draft credit note against the sent invoice, issued today; empty if no such invoice.
     * A draft, a void invoice or a credit note is refused.
     */
    @Transactional
    public Optional<Invoice> creditNote(Long invoiceId) {
        return invoices.findWithLinesById(invoiceId).map(original -> {
            if (original.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note cannot itself be credited.");
            }
            if (original.isDraft()) {
                throw new InvoiceRejectedException("Only a sent invoice can be credited.");
            }
            if (original.isVoid()) {
                throw new InvoiceRejectedException("A void invoice cannot be credited.");
            }
            return invoices.saveAndFlush(original.creditNote(today.date()));
        });
    }

    /**
     * An invoice for a client with payment terms is due that many days after it is issued; otherwise
     * as {@link #dueDateFor(LocalDate)}.
     */
    private LocalDate dueDateFor(Long clientId, LocalDate issued) {
        return clients.findById(clientId)
                .map(Client::getTermsDays)
                .map(days -> issued.plusDays(days))
                .orElseGet(() -> dueDateFor(issued));
    }

    /** A new invoice is due on the last day of the month after the month it is issued in. */
    static LocalDate dueDateFor(LocalDate issued) {
        LocalDate nextMonth = issued.plusMonths(1);
        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
    }

    /**
     * Adds a line to an invoice; empty if no such invoice. The line has already been checked. A sent
     * invoice with no payments goes back to draft; one with a payment refuses it.
     */
    @Transactional
    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            boolean reopened = reopenForChange(invoice, "A paid invoice cannot take new lines.");
            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate));
            invoices.saveAndFlush(invoice);
            if (reopened) {
                audit.record("INVOICE_REOPENED id=" + invoice.getId());
            }
        });
        return found;
    }

    /**
     * Removes a line from an invoice; empty if no such invoice or line. Refused when what is left would
     * be less than a fixed discount. A sent invoice with no payments goes back to draft; one with a
     * payment refuses it.
     */
    @Transactional
    public Optional<Invoice> removeLine(Long invoiceId, Long lineId) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        if (found.isEmpty()) {
            return found;
        }
        Invoice invoice = found.get();
        if (!invoice.hasLine(lineId)) {
            return Optional.empty();
        }
        boolean reopened = reopenForChange(invoice, "A paid invoice cannot have lines removed.");
        invoice.removeLine(lineId);
        invoices.saveAndFlush(invoice);
        if (reopened) {
            audit.record("INVOICE_REOPENED id=" + invoice.getId());
        }
        return found;
    }

    /**
     * Changes a line of an invoice; empty if no such invoice or line. The line has already been
     * checked. Refused when the subtotal would be less than a fixed discount. A sent invoice with no
     * payments goes back to draft; one with a payment refuses it.
     */
    @Transactional
    public Optional<Invoice> updateLine(Long invoiceId, Long lineId, String description, BigDecimal qty,
            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        if (found.isEmpty()) {
            return found;
        }
        Invoice invoice = found.get();
        if (!invoice.hasLine(lineId)) {
            return Optional.empty();
        }
        boolean reopened = reopenForChange(invoice, "A paid invoice cannot have lines changed.");
        invoice.updateLine(lineId, description, qty, unitPrice, taxExempt, discountPct, taxRate);
        invoices.saveAndFlush(invoice);
        if (reopened) {
            audit.record("INVOICE_REOPENED id=" + invoice.getId());
        }
        return found;
    }

    /**
     * Gives an invoice a percentage discount, or a fixed amount off when one is given; the one given
     * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
     * over the subtotal is refused, as is a discount taking off more than a fifth of the subtotal
     * (after the cap) without a reason. A sent invoice with no payments goes back to draft; one with a
     * payment refuses it.
     */
    @Transactional
    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
            BigDecimal discountCap, String discountReason) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note has no discount.");
            }
            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
            if (discountAmount != null) {
                invoice.setDiscountAmount(discountAmount);
            } else {
                invoice.setDiscountPct(discountPct);
            }
            invoice.setDiscountCap(discountCap);
            invoice.setDiscountReason(discountReason);
            if (invoice.discountLacksReason()) {
                throw new InvoiceRejectedException(
                        "A discount of more than 20% of the subtotal needs a reason.");
            }
            invoices.saveAndFlush(invoice);
            if (reopened) {
                audit.record("INVOICE_REOPENED id=" + invoice.getId());
            }
        });
        return found;
    }

    /**
     * Sets a draft's due date by hand, kept when it is sent; empty if no such invoice. A date before
     * the issue date or more than {@link Invoice#MAX_DUE_DAYS} days after it is refused, as is any
     * invoice that is not a draft.
     */
    @Transactional
    public Optional<Invoice> setDueDate(Long invoiceId, LocalDate dueDate) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("Only a draft's due date can be set.");
            }
            invoice.setDueDate(dueDate);
            invoices.saveAndFlush(invoice);
        });
        return found;
    }

    /**
     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
     * back to draft, to be sent again; an invoice with any payment is refused with the message.
     * Whether it went back to draft.
     */
    private boolean reopenForChange(Invoice invoice, String refusal) {
        if (invoice.isDraft()) {
            return false;
        }
        if (invoice.isVoid()) {
            throw new InvoiceRejectedException("A void invoice cannot be changed.");
        }
        if (invoice.isCreditNote()) {
            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
        }
        if (invoice.hasCreditNotesIssued()) {
            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
        }
        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
            throw new InvoiceRejectedException(refusal);
        }
        invoice.reopen();
        return true;
    }

    /**
     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
     * before today, is refused.
     */
    @Transactional
    public Optional<Invoice> send(Long invoiceId) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isVoid()) {
                throw new InvoiceRejectedException("A void invoice cannot be sent.");
            }
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("This invoice has already been sent.");
            }
            if (invoice.getLines().isEmpty()) {
                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
            }
            if (invoice.isCreditNote()) {
                String refusal = creditNoteRefusal(invoice);
                if (refusal != null) {
                    throw new InvoiceRejectedException(refusal);
                }
                issue(invoice);
                return;
            }
            if (invoice.discountLacksReason()) {
                throw new InvoiceRejectedException(
                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
            }
            if (invoice.dueDatePassedBy(today.date())) {
                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
                        + ") is already past; set a later due date before sending the invoice.");
            }
            markSent(invoice);
        });
        return found;
    }

    /**
     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
     * hand is already past, stay drafts.
     */
    @Transactional
    public void sendAllDrafts(Long clientId) {
        invoices.findByClientIdOrderByIdAsc(clientId).stream()
                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
                        && !invoice.dueDatePassedBy(today.date()))
                .forEach(invoice -> {
                    if (!invoice.isCreditNote()) {
                        markSent(invoice);
                    } else if (creditNoteRefusal(invoice) == null) {
                        issue(invoice);
                    }
                });
    }

    /**
     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
     * invoice (not void) that still owes at least the credit note's grand total.
     */
    private String creditNoteRefusal(Invoice note) {
        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElse(null);
        if (original == null || original.isDraft() || original.isVoid()) {
            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
        }
        // Read again what it has been credited: another credit note may just have been issued against it.
        entityManager.refresh(original);
        BigDecimal rate = taxRate.percent();
        BigDecimal due = original.amountDue(paid(List.of(original)).get(original.getId()), rate);
        BigDecimal total = note.total(rate);
        if (total.compareTo(due) > 0) {
            return "The credit note's total of $" + total.toPlainString() + " is more than the $"
                    + due.setScale(2, RoundingMode.HALF_UP).toPlainString() + " " + original.number()
                    + " still owes.";
        }
        return null;
    }

    /** Issues the draft credit note today, its grand total coming off its original, and records it in the audit. */
    private void issue(Invoice note) {
        BigDecimal rate = taxRate.percent();
        note.markIssued(today.date(), rate);
        invoices.saveAndFlush(note);
        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
                + note.getCreditOf() + " total=" + note.total(rate).toPlainString());
    }

    /**
     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
     * client's credit on it (see {@link #applyCredit}).
     */
    private void markSent(Invoice invoice) {
        LocalDate issued = today.date();
        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
        invoices.saveAndFlush(invoice);
        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
                + " total=" + invoice.total(taxRate.percent()).toPlainString());
        applyCredit(invoice);
    }

    /**
     * Uses the client's credit on the invoice just sent, up to what it has due: the oldest payment's
     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
     */
    private void applyCredit(Invoice invoice) {
        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
        LocalDate now = today.date();
        boolean used = false;
        for (Payment payment : payments.findForClient(invoice.getClientId())) {
            if (due.signum() <= 0) {
                break;
            }
            BigDecimal credit = payment.credit();
            if (credit.signum() <= 0) {
                continue;
            }
            BigDecimal part = credit.min(due);
            payment.apply(invoice.getId(), part, now);
            payments.saveAndFlush(payment);
            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
            due = due.subtract(part);
            used = true;
        }
        if (used) {
            recordWriteOff(invoice);
        }
    }

    /**
     * Records a deposit of the amount on the date from the client: the whole amount is held on the
     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
     * client. The amount has already been checked; a date after today is refused.
     */
    @Transactional
    public Optional<Payment> recordDeposit(Long clientId, BigDecimal amount, LocalDate date) {
        if (clients.findById(clientId).isEmpty()) {
            return Optional.empty();
        }
        LocalDate now = today.date();
        if (date.isAfter(now)) {
            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
        }
        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
        return Optional.of(payment);
    }

    /**
     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
     * such client. The amount has already been checked; a date after today or before a payment it
     * would come from, or an amount more than the client's credit, is refused.
     */
    @Transactional
    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
        if (clients.findById(clientId).isEmpty()) {
            return Optional.empty();
        }
        LocalDate now = today.date();
        if (date.isAfter(now)) {
            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
        }
        List<Payment> from = new ArrayList<>();
        List<BigDecimal> parts = new ArrayList<>();
        BigDecimal left = amount;
        BigDecimal credit = BigDecimal.ZERO;
        for (Payment payment : payments.findForClient(clientId)) {
            BigDecimal unused = payment.credit();
            if (unused.signum() <= 0) {
                continue;
            }
            credit = credit.add(unused);
            if (left.signum() <= 0) {
                continue;
            }
            BigDecimal part = unused.min(left);
            if (date.isBefore(payment.getDate())) {
                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
                        + payment.getDate() + " it would come from.");
            }
            from.add(payment);
            parts.add(part);
            left = left.subtract(part);
        }
        if (left.signum() > 0) {
            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
        }
        for (int i = 0; i < from.size(); i++) {
            Payment payment = from.get(i);
            payment.refund(parts.get(i));
            payments.saveAndFlush(payment);
            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
        }
        return Optional.of(clientId);
    }

    /** The unused credit of each client that has any, by client id. */
    @Transactional(readOnly = true)
    public Map<Long, BigDecimal> credits() {
        Map<Long, BigDecimal> credits = new HashMap<>();
        for (Payment payment : payments.findNotReversed()) {
            BigDecimal credit = payment.credit();
            if (credit.signum() > 0) {
                credits.merge(payment.getClientId(), credit, BigDecimal::add);
            }
        }
        return credits;
    }

    /**
     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
     * draft, an invoice already void, or one with any payment is refused.
     */
    @Transactional
    public Optional<Invoice> voidInvoice(Long invoiceId) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isVoid()) {
                throw new InvoiceRejectedException("This invoice is already void.");
            }
            if (invoice.isDraft()) {
                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
            }
            if (invoice.isCreditNote()) {
                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
            }
            if (invoice.hasCreditNotesIssued()) {
                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
            }
            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
            }
            invoice.markVoid();
            invoices.saveAndFlush(invoice);
            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
        });
        return found;
    }

    /** The payments made to the invoice, oldest first, with their allocations. */
    @Transactional(readOnly = true)
    public List<Payment> payments(Long invoiceId) {
        return payments.findForInvoice(invoiceId);
    }

    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
    @Transactional(readOnly = true)
    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
        Map<Long, LocalDate> paidOn = new HashMap<>();
        if (list.isEmpty()) {
            return paidOn;
        }
        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
        BigDecimal rate = taxRate.percent();
        for (Invoice i : list) {
            LocalDate on = i.paidOn(found, rate);
            if (on != null) {
                paidOn.put(i.getId(), on);
            }
        }
        return paidOn;
    }

    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
    @Transactional(readOnly = true)
    public Map<Long, BigDecimal> paid(List<Invoice> list) {
        Map<Long, BigDecimal> paid = new HashMap<>();
        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
        if (!list.isEmpty()) {
            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
            }
        }
        return paid;
    }

    /**
     * Records a payment of the amount on the date against a sent invoice that still has something
     * due, and records it in the audit; empty if no such invoice. The amount has already been
     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
     * invoice already paid, or a date after today
     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
     * already been checked; one that belongs to a different invoice is refused.
     */
    @Transactional
    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isDraft()) {
                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
            }
            if (invoice.isVoid()) {
                throw new InvoiceRejectedException("A void invoice takes no payments.");
            }
            if (invoice.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note takes no payments.");
            }
            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
            if (due.signum() <= 0) {
                throw new InvoiceRejectedException("This invoice has already been paid.");
            }
            BigDecimal applied = amount.min(due);
            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
                throw new InvoiceRejectedException("A part payment must be at least $"
                        + invoice.minimumPart(taxRate.percent()).toPlainString()
                        + " (10% of the total), unless it settles the invoice.");
            }
            LocalDate now = today.date();
            if (date.isAfter(now)) {
                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
            }
            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
                throw new InvoiceRejectedException(
                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
            }
            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
                        + " is the reference of a different invoice; this invoice's is "
                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
            }
            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
            recordWriteOff(invoice);
            recordCreditHeld(payment);
        });
        return found;
    }

    /**
     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
     * paying each off in full before the next.
     * What it pays beyond everything the client owes is held on the client's account as credit; the
     * rest is checked and recorded as a split payment over the invoices it reaches.
     * References (empty when none, each already checked) instead limit the payment to the client's
     * invoices with those references, applied in the same order; one that is not the reference of any
     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
     * as credit.
     * The payment keeps the reference of the first invoice it reaches.
     */
    @Transactional
    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
        List<Invoice> candidates = ofClient;
        if (!references.isEmpty()) {
