256	    /**
257	     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
258	     * back to draft, to be sent again; an invoice with any payment is refused with the message.
259	     * Whether it went back to draft.
260	     */
261	    private boolean reopenForChange(Invoice invoice, String refusal) {
262	        if (invoice.isDraft()) {
263	            return false;
264	        }
265	        if (invoice.isVoid()) {
266	            throw new InvoiceRejectedException("A void invoice cannot be changed.");
267	        }
268	        if (invoice.isCreditNote()) {
269	            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
270	        }
271	        if (invoice.hasCreditNotesIssued()) {
272	            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
273	        }
274	        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
275	            throw new InvoiceRejectedException(refusal);
276	        }
277	        invoice.reopen();
278	        return true;
279	    }
