281	    /**
282	     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
283	     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
284	     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
285	     * before today, is refused.
286	     */
287	    @Transactional
288	    public Optional<Invoice> send(Long invoiceId) {
289	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
290	        found.ifPresent(invoice -> {
291	            if (invoice.isVoid()) {
292	                throw new InvoiceRejectedException("A void invoice cannot be sent.");
293	            }
294	            if (!invoice.isDraft()) {
295	                throw new InvoiceRejectedException("This invoice has already been sent.");
296	            }
297	            if (invoice.getLines().isEmpty()) {
298	                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
299	            }
300	            if (invoice.isCreditNote()) {
301	                String refusal = creditNoteRefusal(invoice);
302	                if (refusal != null) {
303	                    throw new InvoiceRejectedException(refusal);
304	                }
305	                issue(invoice);
306	                return;
307	            }
308	            if (invoice.discountLacksReason()) {
309	                throw new InvoiceRejectedException(
310	                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
311	            }
312	            if (invoice.dueDatePassedBy(today.date())) {
313	                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
314	                        + ") is already past; set a later due date before sending the invoice.");
315	            }
316	            markSent(invoice);
317	        });
318	        return found;
319	    }
