321	    /**
322	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
323	     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
324	     * hand is already past, stay drafts.
325	     */
326	    @Transactional
327	    public void sendAllDrafts(Long clientId) {
328	        invoices.findByClientIdOrderByIdAsc(clientId).stream()
329	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
330	                        && !invoice.dueDatePassedBy(today.date()))
331	                .forEach(invoice -> {
332	                    if (!invoice.isCreditNote()) {
333	                        markSent(invoice);
334	                    } else if (creditNoteRefusal(invoice) == null) {
335	                        issue(invoice);
336	                    }
337	                });
338	    }
