340	    /**
341	     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
342	     * invoice (not void) that still owes at least the credit note's grand total.
343	     */
344	    private String creditNoteRefusal(Invoice note) {
345	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElse(null);
346	        if (original == null || original.isDraft() || original.isVoid()) {
347	            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
348	        }
349	        // Read again what it has been credited: another credit note may just have been issued against it.
350	        entityManager.refresh(original);
351	        BigDecimal rate = taxRate.percent();
352	        BigDecimal due = original.amountDue(paid(List.of(original)).get(original.getId()), rate);
353	        BigDecimal total = note.total(rate);
354	        if (total.compareTo(due) > 0) {
355	            return "The credit note's total of $" + total.toPlainString() + " is more than the $"
356	                    + due.setScale(2, RoundingMode.HALF_UP).toPlainString() + " " + original.number()
357	                    + " still owes.";
358	        }
359	        return null;
360	    }
