362	    /** Issues the draft credit note today, its grand total coming off its original, and records it in the audit. */
363	    private void issue(Invoice note) {
364	        BigDecimal rate = taxRate.percent();
365	        note.markIssued(today.date(), rate);
366	        invoices.saveAndFlush(note);
367	        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
368	                + note.getCreditOf() + " total=" + note.total(rate).toPlainString());
369	    }
