371	    /**
372	     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
373	     * client's credit on it (see {@link #applyCredit}).
374	     */
375	    private void markSent(Invoice invoice) {
376	        LocalDate issued = today.date();
377	        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
378	        invoices.saveAndFlush(invoice);
379	        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
380	                + " total=" + invoice.total(taxRate.percent()).toPlainString());
381	        applyCredit(invoice);
382	    }
