384	    /**
385	     * Uses the client's credit on the invoice just sent, up to what it has due: the oldest payment's
386	     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
387	     */
388	    private void applyCredit(Invoice invoice) {
389	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
390	        LocalDate now = today.date();
391	        boolean used = false;
392	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
393	            if (due.signum() <= 0) {
394	                break;
395	            }
396	            BigDecimal credit = payment.credit();
397	            if (credit.signum() <= 0) {
398	                continue;
399	            }
400	            BigDecimal part = credit.min(due);
401	            payment.apply(invoice.getId(), part, now);
402	            payments.saveAndFlush(payment);
403	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
404	                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
405	            due = due.subtract(part);
406	            used = true;
407	        }
408	        if (used) {
409	            recordWriteOff(invoice);
410	        }
411	    }
