413	    /**
414	     * Records a deposit of the amount on the date from the client: the whole amount is held on the
415	     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
416	     * client. The amount has already been checked; a date after today is refused.
417	     */
418	    @Transactional
419	    public Optional<Payment> recordDeposit(Long clientId, BigDecimal amount, LocalDate date) {
420	        if (clients.findById(clientId).isEmpty()) {
421	            return Optional.empty();
422	        }
423	        LocalDate now = today.date();
424	        if (date.isAfter(now)) {
425	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
426	        }
427	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
428	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
429	                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
430	        return Optional.of(payment);
431	    }
432	
433	    /**
434	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
435	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
436	     * such client. The amount has already been checked; a date after today or before a payment it
437	     * would come from, or an amount more than the client's credit, is refused.
438	     */
439	    @Transactional
440	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
441	        if (clients.findById(clientId).isEmpty()) {
442	            return Optional.empty();
443	        }
444	        LocalDate now = today.date();
445	        if (date.isAfter(now)) {
446	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
447	        }
448	        List<Payment> from = new ArrayList<>();
449	        List<BigDecimal> parts = new ArrayList<>();
450	        BigDecimal left = amount;
451	        BigDecimal credit = BigDecimal.ZERO;
452	        for (Payment payment : payments.findForClient(clientId)) {
453	            BigDecimal unused = payment.credit();
454	            if (unused.signum() <= 0) {
455	                continue;
456	            }
457	            credit = credit.add(unused);
458	            if (left.signum() <= 0) {
459	                continue;
460	            }
461	            BigDecimal part = unused.min(left);
462	            if (date.isBefore(payment.getDate())) {
463	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
464	                        + payment.getDate() + " it would come from.");
465	            }
466	            from.add(payment);
467	            parts.add(part);
468	            left = left.subtract(part);
469	        }
470	        if (left.signum() > 0) {
471	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
472	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
473	        }
474	        for (int i = 0; i < from.size(); i++) {
475	            Payment payment = from.get(i);
476	            payment.refund(parts.get(i));
477	            payments.saveAndFlush(payment);
478	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
479	                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
480	        }
481	        return Optional.of(clientId);
482	    }
