484	    /** The unused credit of each client that has any, by client id. */
485	    @Transactional(readOnly = true)
486	    public Map<Long, BigDecimal> credits() {
487	        Map<Long, BigDecimal> credits = new HashMap<>();
488	        for (Payment payment : payments.findNotReversed()) {
489	            BigDecimal credit = payment.credit();
490	            if (credit.signum() > 0) {
491	                credits.merge(payment.getClientId(), credit, BigDecimal::add);
492	            }
493	        }
494	        return credits;
495	    }
