551	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
552	    @Transactional(readOnly = true)
553	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
554	        Map<Long, BigDecimal> paid = new HashMap<>();
555	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
556	        if (!list.isEmpty()) {
557	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
