564	    /**
565	     * Records a payment of the amount on the date against a sent invoice that still has something
566	     * due, and records it in the audit; empty if no such invoice. The amount has already been
567	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
568	     * invoice already paid, or a date after today
569	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
570	     * already been checked; one that belongs to a different invoice is refused.
571	     */
572	    @Transactional
573	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
574	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
575	        found.ifPresent(invoice -> {
576	            if (invoice.isDraft()) {
577	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
578	            }
579	            if (invoice.isVoid()) {
580	                throw new InvoiceRejectedException("A void invoice takes no payments.");
581	            }
582	            if (invoice.isCreditNote()) {
583	                throw new InvoiceRejectedException("A credit note takes no payments.");
584	            }
585	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
586	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
587	            if (due.signum() <= 0) {
588	                throw new InvoiceRejectedException("This invoice has already been paid.");
589	            }
590	            BigDecimal applied = amount.min(due);
591	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
592	                throw new InvoiceRejectedException("A part payment must be at least $"
593	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
594	                        + " (10% of the total), unless it settles the invoice.");
595	            }
596	            LocalDate now = today.date();
597	            if (date.isAfter(now)) {
598	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
599	            }
600	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
601	                throw new InvoiceRejectedException(
602	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
603	            }
604	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
605	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
606	                        + " is the reference of a different invoice; this invoice's is "
607	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
608	            }
609	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
610	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
611	                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
612	            recordWriteOff(invoice);
613	            recordCreditHeld(payment);
614	        });
615	        return found;
616	    }
