618	    /**
619	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
620	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
621	     * paying each off in full before the next.
622	     * What it pays beyond everything the client owes is held on the client's account as credit; the
623	     * rest is checked and recorded as a split payment over the invoices it reaches.
624	     * References (empty when none, each already checked) instead limit the payment to the client's
625	     * invoices with those references, applied in the same order; one that is not the reference of any
626	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
627	     * as credit.
628	     * The payment keeps the reference of the first invoice it reaches.
629	     */
630	    @Transactional
631	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
632	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
633	        List<Invoice> candidates = ofClient;
634	        if (!references.isEmpty()) {
635	            Set<Long> named = new HashSet<>();
636	            for (String reference : references) {
637	                Invoice invoice = ofClient.stream()
638	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
639	                        .findFirst()
640	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
641	                                + " is not the reference of any of this client's invoices."));
642	                String number = InvoiceNumber.of(invoice.getId());
643	                if (invoice.isDraft()) {
644	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
645	                }
646	                if (invoice.isVoid()) {
647	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
648	                }
649	                if (invoice.isCreditNote()) {
650	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
651	                }
652	                named.add(invoice.getId());
653	            }
654	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
655	        }
656	        List<Invoice> sent = candidates.stream()
657	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
658	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
659	                        .thenComparing(Invoice::getId))
660	                .toList();
661	        Map<Long, BigDecimal> paid = paid(sent);
662	        BigDecimal owed = BigDecimal.ZERO;
663	        BigDecimal left = amount;
664	        List<PaymentAllocation> parts = new ArrayList<>();
665	        for (Invoice invoice : sent) {
666	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
667	            if (due.signum() <= 0) {
668	                continue;
669	            }
670	            owed = owed.add(due);
671	            if (left.signum() > 0) {
672	                BigDecimal part = left.min(due);
673	                parts.add(new PaymentAllocation(invoice.getId(), part));
674	                left = left.subtract(part);
675	            }
676	        }
677	        if (owed.signum() <= 0) {
678	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
679	                    : "Those invoices have already been paid.");
680	        }
681	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
682	        return recordSpread(clientId, amount, date, reference, parts, true);
683	    }
684	
685	    /**
686	     * Records one payment of the amount on the date spread over several of the client's invoices, and
687	     * records each part in the audit. The amounts have already been checked to be more than zero; they
688	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
689	     * and be no more than what it still has due. The date must be no later than today nor before any
690	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
691	     * be the reference of one of the invoices.
692	     */
693	    @Transactional
694	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
695	            List<PaymentAllocation> parts) {
696	        return recordSpread(clientId, amount, date, reference, parts, false);
697	    }
698	
699	    /**
700	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
701	     * credit may be held the parts may add up to less than the payment: the rest is held on the
702	     * client's account as credit and recorded in the audit.
703	     */
704	    private Payment recordSpread(Long clientId, BigDecimal amount, LocalDate date, String reference,
705	            List<PaymentAllocation> parts, boolean holdCredit) {
706	        if (parts.isEmpty()) {
707	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
708	        }
709	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
710	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
711	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
712	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
713	        }
714	        LocalDate now = today.date();
715	        if (date.isAfter(now)) {
716	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
717	        }
718	        Set<Long> seen = new HashSet<>();
719	        List<Invoice> spreadOver = new ArrayList<>();
720	        for (PaymentAllocation part : parts) {
721	            if (!seen.add(part.getInvoiceId())) {
722	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
723	            }
724	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
725	                    .filter(i -> i.getClientId().equals(clientId))
726	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
727	            String number = InvoiceNumber.of(invoice.getId());
728	            if (invoice.isDraft()) {
729	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
730	            }
731	            if (invoice.isVoid()) {
732	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
733	            }
734	            if (invoice.isCreditNote()) {
735	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
736	            }
737	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
738	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
739	            if (part.getAmount().compareTo(due) > 0) {
740	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
741	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
742	            }
743	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
744	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
745	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
746	                        + " (10% of its total), unless it settles the invoice.");
747	            }
748	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
749	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
750	                        + " (" + invoice.getIssueDate() + ").");
751	            }
752	            spreadOver.add(invoice);
753	        }
754	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
755	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
756	                    + " is not the reference of any of the invoices being paid.");
757	        }
758	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
759	        for (PaymentAllocation part : parts) {
760	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
761	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
762	        }
763	        spreadOver.forEach(this::recordWriteOff);
764	        recordCreditHeld(payment);
765	        return payment;
766	    }
767	
768	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
769	    private void recordCreditHeld(Payment payment) {
770	        BigDecimal credit = payment.credit();
771	        if (credit.signum() > 0) {
772	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
773	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
774	        }
775	    }
776	
777	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
778	    private void recordWriteOff(Invoice invoice) {
779	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
780	        if (writtenOff.signum() > 0) {
781	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
782	        }
783	    }
784	
785	    /**
786	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
787	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
788	     * had any of its credit refunded, is refused.
789	     */
790	    @Transactional
791	    public Optional<Payment> reversePayment(Long paymentId) {
792	        Optional<Payment> found = payments.findById(paymentId);
793	        found.ifPresent(payment -> {
794	            if (payment.isReversed()) {
795	                throw new InvoiceRejectedException("This payment has already been reversed.");
796	            }
797	            if (payment.getRefunded().signum() > 0) {
798	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
799	            }
800	            payment.reverse();
801	            payments.saveAndFlush(payment);
802	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
803	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
804	        });
805	        return found;
806	    }
807	}
