            <button type="submit" data-testid="discount-form-submit" [disabled]="savingDiscount()">
              Apply discount
            </button>
            @if (discountError()) {
              <p role="alert" data-testid="discount-form-error">{{ discountError() }}</p>
            }
          </form>
        }
      }
